package com.gitlab.secondstarcavalier.controlplane.codegen;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads the per-RPC auth exemption from registry.json (generated by tacplus).
 *
 * <p>tacplus resolves every spelling of the exemption — the retired
 * {@code method_s2s/method_c2s {auth_disabled: true}} and the current
 * {@code (spec.rpc) = {flags: [RPC_FLAG_PUBLIC_NO_AUTH | RPC_FLAG_SELF_AUTHENTICATES]}} —
 * into one normalized {@code auth_disabled} boolean per RPC. That boolean is the
 * canonical answer; re-deriving it from proto text lets the two views drift apart
 * whenever the annotation spelling changes.
 */
public class RegistryAuthExemptions {

	/** Keys are "&lt;proto package&gt;.&lt;Service&gt;/&lt;Rpc&gt;". */
	private final Set<String> exemptRpcs;

	private RegistryAuthExemptions(Set<String> exemptRpcs) {
		this.exemptRpcs = Collections.unmodifiableSet(exemptRpcs);
	}

	/**
	 * Loads registry.json, which tacplus writes as a sibling of the
	 * proto-annotated directory the codegen reads.
	 */
	public static RegistryAuthExemptions loadForProtoDir(Path protoDir) throws IOException {
		Path registry = protoDir.getParent().resolve("registry.json");
		if (!Files.isRegularFile(registry)) {
			throw new IOException("registry.json not found at " + registry
					+ " — it carries the canonical per-RPC auth exemptions; regenerate with tacplus");
		}
		return load(registry);
	}

	public static RegistryAuthExemptions load(Path registryJson) throws IOException {
		JsonObject root;
		try (Reader reader = Files.newBufferedReader(registryJson, StandardCharsets.UTF_8)) {
			root = JsonParser.parseReader(reader).getAsJsonObject();
		}
		Set<String> exempt = new HashSet<>();
		walkNode(root, exempt);
		return new RegistryAuthExemptions(exempt);
	}

	/** True if registry.json marks this RPC as skipping the caller interceptor. */
	public boolean isAuthDisabled(String protoPackage, String serviceName, String rpcName) {
		return exemptRpcs.contains(protoPackage + "." + serviceName + "/" + rpcName);
	}

	/** The full exempt set, as "package.Service/Rpc" keys. */
	public Set<String> exemptRpcs() {
		return exemptRpcs;
	}

	private static void walkNode(JsonObject node, Set<String> exempt) {
		if (node.has("services")) {
			for (JsonElement svcElem : node.getAsJsonArray("services")) {
				if (!svcElem.isJsonObject()) continue;
				JsonObject svc = svcElem.getAsJsonObject();
				String pkg = getString(svc, "package");
				String name = getString(svc, "name");
				if (pkg == null || name == null || !svc.has("rpcs")) continue;
				JsonArray rpcs = svc.getAsJsonArray("rpcs");
				for (JsonElement rpcElem : rpcs) {
					if (!rpcElem.isJsonObject()) continue;
					JsonObject rpc = rpcElem.getAsJsonObject();
					String rpcName = getString(rpc, "rpc");
					if (rpcName == null) continue;
					if (rpc.has("auth_disabled") && rpc.get("auth_disabled").getAsBoolean()) {
						exempt.add(pkg + "." + name + "/" + rpcName);
					}
				}
			}
		}
		if (node.has("children")) {
			for (JsonElement child : node.getAsJsonArray("children")) {
				if (child.isJsonObject()) walkNode(child.getAsJsonObject(), exempt);
			}
		}
	}

	private static String getString(JsonObject obj, String field) {
		JsonElement e = obj.get(field);
		return e == null || e.isJsonNull() ? null : e.getAsString();
	}
}
